// PostHog JavaScript SDK - Self-hosted version
// This is a minimal implementation for offline use
// For production, download the full SDK from https://github.com/PostHog/posthog-js

(function() {
  'use strict';
  
  window.posthog = window.posthog || {};
  
  function PostHog() {
    this.config = {};
    this.initialized = false;
    this.eventQueue = [];
  }
  
  PostHog.prototype.init = function(apiKey, options) {
    this.config.apiKey = apiKey;
    this.config.apiHost = options.api_host || 'https://app.posthog.com';
    this.config.loaded = options.loaded;
    this.initialized = true;
    
    // Process queued events
    this.processQueue();
    
    if (this.config.loaded) {
      this.config.loaded(this);
    }
    
    console.log('PostHog initialized (offline mode)');
  };
  
  PostHog.prototype.capture = function(eventName, properties) {
    const event = {
      event: eventName,
      properties: properties || {},
      timestamp: new Date().toISOString(),
      distinct_id: this.getDistinctId()
    };
    
    if (this.initialized) {
      this.sendEvent(event);
    } else {
      this.eventQueue.push(event);
    }
    
    console.log('PostHog event:', event);
  };
  
  PostHog.prototype.identify = function(distinctId, properties) {
    localStorage.setItem('posthog_distinct_id', distinctId);
    if (properties) {
      this.capture('$identify', properties);
    }
  };
  
  PostHog.prototype.getDistinctId = function() {
    let distinctId = localStorage.getItem('posthog_distinct_id');
    if (!distinctId) {
      distinctId = 'anonymous_' + Math.random().toString(36).substr(2, 9);
      localStorage.setItem('posthog_distinct_id', distinctId);
    }
    return distinctId;
  };
  
  PostHog.prototype.sendEvent = function(event) {
    // In offline mode, just log the event
    // In production, this would send to your PostHog instance
    console.log('PostHog event (offline):', event);
  };
  
  PostHog.prototype.processQueue = function() {
    while (this.eventQueue.length > 0) {
      const event = this.eventQueue.shift();
      this.sendEvent(event);
    }
  };
  
  // Initialize PostHog instance
  window.posthog = new PostHog();
  
})();